-- Renault Zoe (X10) seed: generated by scripts/generate-seed.mjs from
-- the filled intake template at out/zoe/, per the import-car skill.
--
-- REUSE/CREATE summary (reconciled live at generation time):
--   engines: 0 REUSE, 2 NEW (R110, R135)
--   transmissions: 1 unit_code(s) referenced, all resolved live against transmission_units (generic:Single-speed EV)
--   body types: 1 REUSE, 0 NEW
--   drivetrain systems referenced: none (FWD only)
--   brand: NEW. model: Zoe (assumed NEW unless already present).
--
-- Configs: 2 total, one row per 'x' cell across 1 config grid file(s)
-- (configs-Phase 2.csv) — every FK resolves by code/name via a CTE, never a
-- hand-typed UUID.
--
-- No alt_codes drift detected between the template and live data.
--
-- TYPE CASTS: every WITH ... AS (VALUES ...) SELECT ... INSERT block explicitly casts
-- each literal (::integer / ::numeric / ::text) — required by the import-car skill to
-- avoid the all-NULL-column VALUES-CTE type-inference bug (Golf IV/León/Toledo/A3 all
-- hit this on their all-NULL NCAP columns).
--
-- No destructive step in this file — everything is additive INSERT, so it all may run
-- via MCP once reviewed.
--
-- Review-only. NOT executed by this script.

do $$
begin
  if to_regclass('public.catalog_brands') is null then
    raise exception 'catalog_brands does not exist — run the catalog_ schema migration first.';
  end if;
  if not exists (select 1 from catalog_body_types where name = 'Hatchback 5-door') then
    raise exception 'catalog_body_types.''Hatchback 5-door'' is missing — reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'R110' and power_kw = 80) then
    raise exception 'catalog_engines.R110 (power_kw=80) already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'R135' and power_kw = 100) then
    raise exception 'catalog_engines.R135 (power_kw=100) already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if not exists (select 1 from transmission_units where code = 'generic:Single-speed EV' or 'generic:Single-speed EV' = any(alt_codes)) then
    raise exception 'No transmission_units row matches unit_code ''generic:Single-speed EV'' — reconcile is stale, re-check before running.';
  end if;
end $$;

