insert into catalog_phases (model_id, generation_code, phase_label, year_from, year_to, display_name, platform_code, safety_rating, ncap_year, ncap_adult_pct, ncap_child_pct, ncap_pedestrian_pct, ncap_safety_assist_pct, avg_market_price_eur, price_range_min_eur, price_range_max_eur, typical_mileage_range, resale_value_rating, towing_capacity_kg, chassis_type)
select m.id, v.generation_code, v.phase_label, v.year_from, v.year_to, v.display_name, v.platform_code,
  v.safety_rating, v.ncap_year, v.ncap_adult_pct, v.ncap_child_pct, v.ncap_pedestrian_pct, v.ncap_safety_assist_pct,
  v.avg_market_price_eur, v.price_range_min_eur, v.price_range_max_eur, v.typical_mileage_range,
  v.resale_value_rating, v.towing_capacity_kg, v.chassis_type
from (
  values
    ('X10'::text, 'Phase 2'::text, 2019::integer, 2024::integer, 'Zoe (X10) Phase 2 Z.E. 50'::text, 'Renault-Nissan B (Zoe)'::text, 0::integer, 2021::integer, 43::integer, 52::integer, 41::integer, 14::integer, NULL::integer, NULL::integer, NULL::integer, null::text, 'depreciates_fast'::text, NULL::integer, 'monocoque'::text)
) as v(generation_code, phase_label, year_from, year_to, display_name, platform_code,
  safety_rating, ncap_year, ncap_adult_pct, ncap_child_pct, ncap_pedestrian_pct, ncap_safety_assist_pct,
  avg_market_price_eur, price_range_min_eur, price_range_max_eur, typical_mileage_range,
  resale_value_rating, towing_capacity_kg, chassis_type)
join catalog_models m on m.name = 'Zoe'
join catalog_brands cb on cb.id = m.brand_id and cb.name = 'Renault'
where not exists (
  select 1 from catalog_phases cp where cp.model_id = m.id and cp.generation_code = v.generation_code and cp.phase_label = v.phase_label
);

