-- 7. VEHICLE CONFIGURATIONS
--    2 row(s), one per marked 'x' cell. dt = null means no AWD system.
-- ════════════════════════════════════════════════════════════

with
  phase_lookup as (
    select cp.id, cp.phase_label
    from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id
    join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'Renault' and cm.name = 'Zoe' and cp.generation_code = 'X10'
  ),
  body_lookup as (
    select id, name from catalog_body_types
  ),
  engine_lookup as (
    select id, code, power_kw from catalog_engines
  ),
  unit_lookup as (
    select id, code, alt_codes from transmission_units
  ),
  dt_lookup as (
    select id, code from drivetrain_systems where false
  ),
  configs (phase_label, body_name, engine_code, engine_power_kw, unit_code, dt_code, driven_axle, fuel_consumption_l100km, energy_consumption_kwh100km, consumption_cycle, secondary_fuel_type, secondary_consumption_l100km, fuel_consumption_urban_l100km, fuel_consumption_extra_urban_l100km, towing_braked_kg, towing_unbraked_kg, curb_weight_kg, acceleration_0_100, top_speed_kmh, co2_emissions_g_km, ev_range_km) as (
    values
      ('Phase 2'::text, 'Hatchback 5-door'::text, 'R110'::text, 80::integer, 'generic:Single-speed EV'::text, null::text, 'front'::text, null::numeric, 17.2::numeric, 'WLTP'::text, null::text, null::numeric, null::numeric, null::numeric, null::integer, null::integer, 1502::integer, 11.4::numeric, 135::integer, null::integer, 395::integer),
      ('Phase 2'::text, 'Hatchback 5-door'::text, 'R135'::text, 100::integer, 'generic:Single-speed EV'::text, null::text, 'front'::text, null::numeric, 17.7::numeric, 'WLTP'::text, null::text, null::numeric, null::numeric, null::numeric, null::integer, null::integer, 1502::integer, 9.5::numeric, 140::integer, null::integer, 386::integer)
  )
insert into catalog_vehicle_configurations (phase_id, body_type_id, engine_id, unit_id, drivetrain_id, driven_axle, fuel_consumption_l100km, energy_consumption_kwh100km, consumption_cycle, secondary_fuel_type, secondary_consumption_l100km, fuel_consumption_urban_l100km, fuel_consumption_extra_urban_l100km, towing_braked_kg, towing_unbraked_kg, curb_weight_kg, acceleration_0_100, top_speed_kmh, co2_emissions_g_km, ev_range_km)
select p.id, b.id, e.id, u.id, d.id, c.driven_axle, c.fuel_consumption_l100km, c.energy_consumption_kwh100km, c.consumption_cycle, c.secondary_fuel_type, c.secondary_consumption_l100km, c.fuel_consumption_urban_l100km, c.fuel_consumption_extra_urban_l100km, c.towing_braked_kg, c.towing_unbraked_kg, c.curb_weight_kg, c.acceleration_0_100, c.top_speed_kmh, c.co2_emissions_g_km, c.ev_range_km
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on b.name = c.body_name
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on u.code = c.unit_code or c.unit_code = any(u.alt_codes)
left join dt_lookup d on d.code = c.dt_code
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

